import pandas as pd
m=pd.read_csv('/task/output/work/gene_counts_U.tsv',sep='\t',index_col=0)
t2g=pd.read_csv('/task/input/reference/tx2gene.tsv',sep='\t',dtype=str).drop_duplicates('gene_id').set_index('gene_id')
want=['XIST','RPS4Y1','DDX3Y','KDM5D','UTY','EIF1AY','CDKN1A','FOS','JUN','EGR1','GAPDH','ACTB']
rows=[]
for g in want:
 ids=t2g.index[t2g.gene_name==g]
 if len(ids): rows.append([g]+[float(m.loc[ids].sum().sum())])
if rows:
 print(pd.DataFrame(rows,columns=['gene']+list(m.columns)).round(1).to_string(index=False))
else: print('none of requested gene names present')
